Use Object.entries(obj). It returns an array of [key, value] pairs for own enumerable properties.

code:
function ObjectToArray(obj) {
  return Object.entries(obj);
}
console.log(ObjectToArray({ a: 1, b: 2 })); // [ ['a', 1], ['b', 2] ]

real example:
A test iterates over every field in an API response: for (const [key, value] of ObjectToArray(response)) { ... }.

Object.freeze() is shallow by default. To deep‑freeze you must recursively freeze each nested object, or use a utility function.

code:
function deepFreeze(obj) {
  const propNames = Object.getOwnPropertyNames(obj);
  for (const name of propNames) {
    const value = obj[name];
    if (typeof value === 'object' && value !== null && !Object.isFrozen(value)) {
      deepFreeze(value);
    }
  }
  return Object.freeze(obj);
}
const frozen = deepFreeze({ a: 1, inner: { b: 2 } });
console.log(Object.isFrozen(frozen), Object.isFrozen(frozen.inner)); // true, true

real example:
A test config that must never be mutated across test runs deep‑freezes the shared fixture.

Use Object.keys() and filter out the excluded keys.

code:
function getObjectKeysExcluding(obj, excluded) {
  return Object.keys(obj).filter(key => !excluded.includes(key));
}
const user = { name: 'Ana', email: 'ana@test.com', role: 'admin' };
console.log(getObjectKeysExcluding(user, ['email'])); // [ 'name', 'role' ]

real example:
A test builds a selector config without including the internal email field.

delete removes the key entirely from the object; after deletion, the key is gone and in returns false. Setting to undefined keeps the key existing with value undefined; 'key' in obj is true, and the key shows up in Object.keys().

code:
const obj = { a: 1 };
delete obj.a;
console.log('a' in obj);    // false
console.log(Object.keys(obj)); // []

const obj2 = { a: 1 };
obj2.a = undefined;
console.log('a' in obj2);     // true
console.log(Object.keys(obj2)); // [ 'a' ]

real example:
A test cleanup removes a temporary field entirely: delete payload.temp. If it sets payload.temp = undefined the field persists and later code may still reference it.

Use the spread operator with a new key that reads from the source: { ...obj, [destKey]: obj[srcKey] }.

code:
function copyProperty(obj, srcKey, destKey) {
  const { [srcKey]: _, ...rest } = obj;
  return { ...rest, [destKey]: obj[srcKey] };
}
const user = { first: 'Ana' };
const copied = copyProperty(user, 'first', 'name');
console.log(copied); // { name: 'Ana' }
console.log(user.first); // Ana (unchanged)

real example:
A test renames a field from an API response without altering the original payload.

a is 1, and 'a' in obj is true. Destructuring reads the value but does not remove the key from the original object.

code:
const obj = { a: 1 };
const { a } = obj;
console.log(a, 'a' in obj);

real example:
A test extracts a field into a variable while keeping the original object intact for later assertions.

Use destructuring with rest to pull out the old key and add the new key to a new object.

code:
function renameAndRemove(obj, oldKey, newKey) {
  const { [oldKey]: value, ...rest } = obj;
  return { ...rest, [newKey]: value };
}
const user = { firstName: 'Ana' };
const renamed = renameAndRemove(user, 'firstName', 'name' );
console.log(renamed); // { name: 'Ana' }
console.log(user.firstName); // Ana (unchanged)

real example:
A test normalizes a legacy field name from an API response without side effects.

Use 'key in obj' to check first, then delete and return its result.

code:
function safeDelete(obj, key) {
  if (key in obj) {
    delete obj[key];
    return true;
  }
  return false;
}
const obj1 = { a: 1 };
console.log(safeDelete(obj1, 'a')); // true
console.log(safeDelete(obj1, 'b')); // false
console.log(obj1); // {}

real example:
A test teardown safely removes optional fields: if (safeDelete(payload, 'tempId')) { ... }.

Use the spread operator with the source first and defaults second: { ...obj, ...defaults }. This fills in missing keys from defaults.

code:
function objectDefaults(obj, defaults) {
  return { ...obj, ...defaults };
}
const user = { name: 'Ana' };
const filled = objectDefaults(user, { age: 30, role: 'tester' });
console.log(filled); // { name: 'Ana', age: 30, role: 'tester' }

real example:
A test applies default values to a partially filled form: const payload = objectDefaults(submitted, { email: '', role: 'viewer' }).

a is 1, Object.keys(rest) is [ 'b' ]. Destructuring with rest collects all other own string-keyed properties into a new object.

code:
const obj = { a: 1, b: 2 };
const { a, ...rest } = obj;
console.log(a, Object.keys(rest));

