A test extracts one field and works with the remaining fields as a new object.

Walk the object's own property values; if a value is an object (not null, not array), recursively freeze it, then freeze the top level.

code:
function freezeNested(obj) {
  const propNames = Object.getOwnPropertyNames(obj);
  for (const name of propNames) {
    const value = obj[name];
    if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
      freezeNested(value);
    }
  }
  return Object.freeze(obj);
}
const data = { a: 1, inner: { b: 2 } };
const frozen = freezeNested(data);
console.log(Object.isFrozen(frozen.inner)); // true

real example:
A test fixture that must never be mutated across multiple test files deep-freezes the shared data structure.

Use Object.getOwnPropertySymbols(obj). Returns an array of symbol values.

code:
function getOwnPropertySymbols(obj) {
  return Object.getOwnPropertySymbols(obj);
}
const sym = Symbol('id');
const obj = { [sym]: 1, name: 'Ana' };
console.log(getOwnPropertySymbols(obj)); // [ Symbol(id) ]

real example:
A test uses Symbol keys for private fields that should not show up in normal key enumeration.

Combine Object.keys() and Object.getOwnPropertySymbols().

code:
function getAllOwnKeys(obj) {
  return [...Object.keys(obj), ...Object.getOwnPropertySymbols(obj)];
}
const sym = Symbol('id');
const obj = { [sym]: 1, name: 'Ana' };
console.log(getAllOwnKeys(obj)); // [ 'Symbol(id)', 'name' ]

real example:
A test enumerates every key including symbolic ones when building a complete inventory of an API response.
